import { orcaCli } from './orca-cli.mjs'

// Host API 1.0's readContext names the focused workspace's branch and terminals but not its path.
// A terminal handle identifies the workspace exactly; branch plus name is the fallback when it has none.
export async function resolveFocusedWorkspace(orca, { signal } = {}) {
  const context = await orca.host.call('workspace.readContext', {}, { signal })
  if (!context) return { context: null, path: null, via: 'none', candidates: [] }
  const [terminal] = context.terminals
  if (terminal) {
    const result = await orcaCli(['terminal', 'show', '--terminal', terminal.id], { signal })
    const path = (result.terminal ?? result).worktreePath
    if (path) return { context, path, via: 'terminal', candidates: [path] }
  }
  const { worktrees } = await orcaCli(['worktree', 'list', '--limit', '500'], { signal })
  const candidates = matchWorktrees(worktrees, context).map((worktree) => worktree.path)
  return { context, path: candidates.length === 1 ? candidates[0] : null, via: 'branch', candidates }
}

// Orca's CLI reports full refs; readContext reports short branch names.
export function shortBranch(ref = '') {
  return ref.replace(/^refs\/heads\//, '')
}

export function matchWorktrees(worktrees, { branch, displayName }) {
  return worktrees.filter(
    (worktree) =>
      !worktree.isArchived && shortBranch(worktree.branch) === branch && worktree.displayName === displayName
  )
}
// Orca reports WSL workspaces as UNC paths, while the plugin worker always runs on the desktop host.
// Entire has to run where the repo and its login live, so each workspace path maps to a host.

const WSL_UNC = /^\\\\wsl(?:\.localhost|\$)\\([^\\]+)(\\.*)?$/i

export function workspaceHost(workspacePath) {
  const match = WSL_UNC.exec(workspacePath.replaceAll('/', '\\'))
  if (!match) return { kind: 'local', path: workspacePath }
  return { kind: 'wsl', distro: match[1], path: (match[2] ?? '\\').replaceAll('\\', '/') }
}

export function entireCommand(host, args) {
  if (host.kind === 'wsl') {
    // A login shell puts ~/.local/bin on PATH; "$@" passes each argument through without re-parsing.
    return {
      command: 'wsl.exe',
      args: ['-d', host.distro, '--cd', host.path, '-e', 'bash', '-lc', 'exec entire "$@"', 'entire', ...args]
    }
  }
  return { command: 'entire', args, cwd: host.path }
}

export function gitCommand(host, args) {
  if (host.kind === 'wsl') return { command: 'wsl.exe', args: ['-d', host.distro, '--cd', host.path, '-e', 'git', ...args] }
  return { command: 'git', args, cwd: host.path }
}
import { entireCommand } from './hosts.mjs'
import { desktopEnv, run } from './process.mjs'

export function runEntire(host, args, { signal, timeoutMs } = {}) {
  const { command, args: argv, cwd } = entireCommand(host, args)
  return run(command, argv, { cwd, env: entireEnv(), signal, timeoutMs })
}

// Entire sends usage analytics from a detached `entire __send_analytics` child. On Windows that child has
// no console, so every git it runs opens a terminal window. The plugin's calls are background reads, so
// they opt out of analytics; WSLENV carries the opt-out into WSL as well.
export function entireEnv(env = desktopEnv()) {
  return {
    ...env,
    ENTIRE_TELEMETRY_OPTOUT: '1',
    WSLENV: env.WSLENV ? `${env.WSLENV}:ENTIRE_TELEMETRY_OPTOUT` : 'ENTIRE_TELEMETRY_OPTOUT'
  }
}

// Entire explains a failure in one line, on stderr or stdout depending on the command.
export function failureLine(result) {
  if (result.timedOut) return `timed out after ${result.ms} ms`
  return (result.stderr.trim() || result.stdout.trim() || `exit ${result.code}`).split('\n')[0]
}
import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { desktopEnv, run } from './process.mjs'

// The worker runs inside Orca's own binary (ELECTRON_RUN_AS_NODE), so Orca's CLI ships beside it.
// Verified on Windows; check the layout before relying on it on macOS.
export function orcaCliPath(execPath = process.execPath, platform = process.platform) {
  const cli = join(dirname(execPath), 'resources', 'bin', platform === 'win32' ? 'orca.exe' : 'orca')
  return existsSync(cli) ? cli : null
}

export async function orcaCli(args, { signal } = {}) {
  const cli = orcaCliPath()
  if (!cli) throw new Error(`Orca CLI not found beside ${process.execPath}`)
  const name = `orca ${args.slice(0, 2).join(' ')}`
  const { code, stdout } = await run(cli, [...args, '--json'], { env: desktopEnv(), signal })
  let reply
  try {
    reply = JSON.parse(stdout)
  } catch {
    throw new Error(`${name} printed no JSON (exit ${code})`)
  }
  if (!reply.ok) throw new Error(`${name}: ${reply.error?.message ?? 'failed'}`)
  return reply.result
}
import { spawn } from 'node:child_process'
import { win32 } from 'node:path'

// Orca stops waiting for a plugin command after 30 s, so each child process gets a shorter budget.
const CHILD_TIMEOUT_MS = 15_000

export function run(command, args, { cwd, env = process.env, signal, timeoutMs = CHILD_TIMEOUT_MS } = {}) {
  return new Promise((resolve, reject) => {
    const started = Date.now()
    const child = spawn(command, args, { cwd, env, signal, windowsHide: true })
    const stdout = []
    const stderr = []
    let timedOut = false
    const timer = setTimeout(() => {
      timedOut = true
      child.kill()
    }, timeoutMs)
    child.stdout.on('data', (chunk) => stdout.push(chunk))
    child.stderr.on('data', (chunk) => stderr.push(chunk))
    child.on('error', (error) => {
      clearTimeout(timer)
      reject(error)
    })
    child.on('close', (code) => {
      clearTimeout(timer)
      resolve({
        code,
        timedOut,
        stdout: Buffer.concat(stdout).toString('utf8'),
        stderr: Buffer.concat(stderr).toString('utf8'),
        ms: Date.now() - started
      })
    })
  })
}

// The worker env is an allowlist without APPDATA or LOCALAPPDATA, which Windows CLIs (Orca's included)
// use to find their data. Derive them from USERPROFILE when they are missing.
export function desktopEnv(env = process.env, platform = process.platform) {
  if (platform !== 'win32' || !env.USERPROFILE) return env
  return {
    APPDATA: win32.join(env.USERPROFILE, 'AppData', 'Roaming'),
    LOCALAPPDATA: win32.join(env.USERPROFILE, 'AppData', 'Local'),
    ...env
  }
}
import { gitCommand } from './hosts.mjs'
import { desktopEnv, run } from './process.mjs'

export function runGit(host, args, { signal } = {}) {
  const { command, args: argv, cwd } = gitCommand(host, args)
  return run(command, argv, { cwd, env: desktopEnv(), signal })
}

// Branch names come from Entire, so only a plain ref name ever reaches git.
export function safeRef(name) {
  return typeof name === 'string' && /^[\w][\w./-]{0,200}$/.test(name) && !name.includes('..') ? name : null
}

// `git diff --shortstat` prints " 3 files changed, 458 insertions(+), 20 deletions(-)", leaving out zero counts.
export function parseShortstat(out) {
  const count = (pattern) => Number(pattern.exec(out)?.[1] ?? 0)
  return { files: count(/(\d+) files? changed/), additions: count(/(\d+) insertions?/), deletions: count(/(\d+) deletions?/) }
}

// The branch's changes against its base, as Entire's web view shows them. Null when git can't tell.
export async function diffStat(host, base, { signal } = {}) {
  for (const ref of [`origin/${base}`, base]) {
    const result = await runGit(host, ['diff', '--shortstat', `${ref}...HEAD`], { signal }).catch(() => null)
    if (result?.code === 0) return parseShortstat(result.stdout)
  }
  return null
}
// "Entire: Check connection" walks every link the plugin depends on and reports one line per link.
export function connectionReport(orca, snapshot) {
  return [`Orca host API ${orca.api.major}.${orca.api.minor} · Node ${process.version} on ${process.platform}`, ...reportLines(snapshot)].join('\n')
}

export function reportLines({ workspace, problem, steps }) {
  const lines = []
  if (workspace?.where) lines.push(`✓ ${workspace.name} on ${workspace.branch} → ${workspace.where} (via ${workspace.via})`)
  if (problem) lines.push(`✗ ${problem}`)
  for (const step of steps) {
    const mark = step.ok ? '✓' : step.optional ? '·' : '✗'
    lines.push(`${mark} ${step.label}: ${step.text}${step.ok ? ` (${step.ms} ms)` : ''}`)
  }
  return lines
}

// Orca's notifications take a title of up to 120 characters and a body of up to 1000.
export function connectionNotice(report) {
  const [, ...details] = report.split('\n')
  const ok = !details.some((line) => line.startsWith('✗'))
  return {
    title: ok ? 'Entire: connected' : 'Entire: connection problem',
    body: details.join('\n').slice(0, 1000)
  }
}
// Host API 1.0 has no event for focus moving to another workspace, so the worker asks which workspace
// is focused every few seconds and decides when to read Entire for it again.
export const FOCUS_POLL_MS = 5000
// The focused workspace is read again this often, even when nothing else asks.
export const AUTO_REFRESH_MS = 5 * 60_000
// Switching to a workspace the panel shows data for younger than this shows what the panel has.
// panel/template.html uses the same age to decide whether to show "Checking…".
export const SWITCH_FRESH_MS = 60_000
const MAX_KEPT = 50

// readContext and snapshots name a workspace the same way: display name, branch and terminal ids.
export function focusKey({ name, branch, terminals = [] }) {
  return JSON.stringify([name, branch, [...terminals].sort()])
}

export function contextKey(context) {
  return context ? focusKey({ name: context.displayName, branch: context.branch, terminals: context.terminals.map((terminal) => terminal.id) }) : null
}

export function createFocusTracker({ now = Date.now } = {}) {
  const readAt = new Map()
  let focused = null

  function markRead(key, at = now()) {
    if (!key) return
    readAt.delete(key)
    readAt.set(key, at)
    if (readAt.size > MAX_KEPT) readAt.delete(readAt.keys().next().value)
  }

  return {
    markRead,
    // Why the focused workspace is due a read, 'switch' or 'timer', or null when it isn't. A due read
    // counts as a read, so a lookup that keeps failing is retried on the same schedule, not every poll.
    // On a switch, what counts is the panel's own entry, read by shownAt (its time in ms, or null):
    // the worker's last read may have been for another branch, or skipped its unchanged write.
    dueRead(key, { shownAt = () => null } = {}) {
      const switched = key !== focused
      focused = key
      if (!key) return null
      if (switched) {
        const at = shownAt()
        if (at !== null && now() - at < SWITCH_FRESH_MS) {
          // The timer counts from the shown data's read.
          markRead(key, at)
          return null
        }
      } else if (readAt.has(key) && now() - readAt.get(key) < AUTO_REFRESH_MS) {
        return null
      }
      markRead(key)
      return switched ? 'switch' : 'timer'
    }
  }
}

// Orca forks this module in a Node worker on the desktop host and calls activate once.
import manifest from '../../orca-plugin.json' with { type: 'json' }
import { connectionNotice, connectionReport } from './doctor.mjs'
import { contextKey, createFocusTracker, FOCUS_POLL_MS, focusKey } from './focus.mjs'
import { panelEntry, shownAt, updatePanel } from './panel.mjs'
import { auditLogPath, watchRefreshRequests } from './refresh-requests.mjs'
import { collectSnapshot } from './snapshot.mjs'

// Entire writes its checkpoint data as an agent stops, so let it settle before reading.
const AGENT_SETTLE_MS = 3000

export default function activate(orca) {
  const notify = (notice, signal) =>
    orca.host.call('notifications.show', notice, { signal }).catch((error) => {
      console.error(`Notification failed: ${error.message}`)
    })

  const focus = createFocusTracker()
  let running = 0

  // One snapshot feeds both the report and the panel.
  async function refresh(signal, { onlyIfChanged = false } = {}) {
    running++
    try {
      const snapshot = await collectSnapshot(orca, { signal })
      if (snapshot.workspace) focus.markRead(focusKey(snapshot.workspace))
      const report = connectionReport(orca, snapshot)
      // Orca 1.4.245's command palette drops a command's result, so the report also goes to the plugin's Logs.
      console.log(report)
      let panel = 'no workspace'
      if (snapshot.workspace) panel = await updatePanel(panelEntry(snapshot), { onlyIfChanged }).catch((error) => `failed: ${error.message}`)
      if (panel !== 'updated') console.log(`Panel not updated: ${panel}`)
      return { report, panel }
    } finally {
      running--
    }
  }

  orca.commands.register('doctor', async (_args, { signal }) => {
    const { report } = await refresh(signal)
    await notify(connectionNotice(report), signal)
    return report
  })

  orca.commands.register('refresh', async (_args, { signal }) => {
    const { report, panel } = await refresh(signal)
    if (panel === 'installed copy') {
      await notify({ title: 'Entire: panel not updated', body: 'The panel updates only when Orca runs this plugin from a Development folder.' }, signal)
    } else if (panel !== 'updated') {
      await notify({ title: 'Entire: panel not updated', body: `${panel}\n${report.split('\n').slice(1).join('\n')}`.slice(0, 1000) }, signal)
    }
    return `Panel ${panel}`
  })

  // Background refreshes run one at a time, and a request that arrives while one waits joins it. The
  // joined refresh skips an unchanged write only if every request in it allowed that.
  let timer = null
  let queue = Promise.resolve()
  let waiting = false
  let quiet = true
  function queueRefresh(delayMs, { onlyIfChanged = false } = {}) {
    quiet &&= onlyIfChanged
    clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      if (waiting) return
      waiting = true
      queue = queue
        .then(() => {
          waiting = false
          const options = { onlyIfChanged: quiet }
          quiet = true
          return refresh(undefined, options)
        })
        .catch((error) => console.error(`Refresh failed: ${error.message}`))
    }, delayMs)
  }

  // An agent finishing is when Entire has new checkpoints and sessions to show.
  orca.events.on('agent.status.changed', (event) => {
    if ((event.mainAgent?.state ?? event.state) === 'done') queueRefresh(AGENT_SETTLE_MS, { onlyIfChanged: true })
  })

  // The panel's refresh button reaches the worker through Orca's audit log, while the worker runs.
  const auditLog = auditLogPath()
  if (auditLog) watchRefreshRequests(auditLog, `plugin:${manifest.publisher}.${manifest.id}`, () => queueRefresh(0))

  // Read the focused workspace when focus moves to it and every few minutes after. The poll is also a
  // host call, which keeps Orca from stopping the worker as idle, so ↻ keeps working until Orca quits.
  // A refresh already running or scheduled reads the focused workspace anyway. After a switch the
  // panel shows "Checking…" until it is rewritten, so only the timed read may skip an unchanged write.
  setInterval(() => {
    orca.host.call('workspace.readContext', {}).then(
      (context) => {
        if (running || waiting || timer) return
        const reason = focus.dueRead(contextKey(context), { shownAt: () => shownAt(context) })
        if (!reason) return
        console.log(`Checking Entire for ${context.displayName} on ${context.branch} (${reason})`)
        queueRefresh(0, { onlyIfChanged: reason === 'timer' })
      },
      () => {}
    )
  }, FOCUS_POLL_MS).unref()
}
import { failureLine, runEntire } from './entire-cli.mjs'
import { diffStat, safeRef } from './git.mjs'
import { workspaceHost } from './hosts.mjs'
import { trailSummary } from './trail.mjs'
import { resolveFocusedWorkspace } from './workspace.mjs'

const VERSION = { key: 'version', label: 'Entire CLI', args: ['--version'], parse: (out) => out.trim().split('\n')[0] }

// Each step keeps its own outcome, so one failed call (a branch without a trail, say) hides nothing else.
const STEPS = [
  {
    key: 'status',
    label: 'Repo',
    args: ['status', '--json'],
    parse: JSON.parse,
    summarize: (status) =>
      status.enabled ? `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}` : 'Entire is not enabled here'
  },
  // A branch without a trail is normal, so this step reports instead of failing the check.
  {
    key: 'trail',
    label: 'Trail',
    args: ['trail', 'show', '--json'],
    optional: true,
    parse: JSON.parse,
    summarize: (trail) => `#${trail.number} ${trail.title} · ${trail.status}`
  },
  {
    key: 'checkpoints',
    label: 'Checkpoints',
    args: ['checkpoint', 'list', '--json'],
    parse: JSON.parse,
    summarize: (list) => `${list.length} on this branch`
  }
]

// Fetched alongside the steps for the panel only: the connection check doesn't report them. Every status,
// so resolved findings and how they were fixed show too, as in Entire's web view.
const FINDINGS = {
  key: 'findings',
  label: 'Findings',
  args: ['trail', 'finding', 'list', '--status', 'any', '--freshness', 'any', '--json'],
  parse: JSON.parse
}

// The panel keeps the newest checkpoints only.
const CHECKPOINT_LIMIT = 20

// Everything the panel and "Entire: Check connection" show for the focused workspace.
export async function collectSnapshot(orca, { signal } = {}) {
  const snapshot = { at: new Date().toISOString(), workspace: null, problem: null, steps: [], data: {} }

  let resolved
  try {
    resolved = await resolveFocusedWorkspace(orca, { signal })
  } catch (error) {
    return { ...snapshot, problem: `Workspace lookup failed: ${error.message}` }
  }
  const { context, path, via, candidates } = resolved
  if (!context) return { ...snapshot, problem: 'No workspace is focused' }
  const workspace = {
    name: context.displayName,
    branch: context.branch,
    terminals: context.terminals.map((terminal) => terminal.id),
    path,
    via
  }
  if (!path) {
    // Without a terminal, only branch and name identify the workspace, and many repos share "main".
    const why = candidates.length > 0 ? `${candidates.length} workspaces match it` : 'no workspace matches it'
    return { ...snapshot, workspace, problem: `${context.displayName} on ${context.branch}: ${why}. Open a terminal in it and try again.` }
  }
  const host = workspaceHost(path)
  workspace.where = host.kind === 'wsl' ? `WSL ${host.distro} ${host.path}` : path

  const version = await runStep(host, VERSION, signal)
  if (!version.ok) return { ...snapshot, workspace, steps: [version.step] }
  const [findings, ...results] = await Promise.all([FINDINGS, ...STEPS].map((step) => runStep(host, step, signal)))
  const data = Object.fromEntries(results.filter((result) => result.ok).map((result) => [result.step.key, result.value]))
  if (data.checkpoints) data.checkpoints = data.checkpoints.slice(0, CHECKPOINT_LIMIT)
  if (data.trail) {
    const found = findings.ok ? findings.value : null
    const base = safeRef(found?.trail?.base)
    data.trail = trailSummary(data.trail, { findings: found, diff: base ? await diffStat(host, base, { signal }) : null })
  }
  return { ...snapshot, workspace, steps: [version.step, ...results.map((result) => result.step)], data }
}

async function runStep(host, { key, label, args, optional = false, parse, summarize = (value) => value }, signal) {
  const step = { key, label, optional, ok: false }
  let result
  try {
    result = await runEntire(host, args, { signal })
  } catch (error) {
    return { ok: false, step: { ...step, text: error.message } }
  }
  if (result.code !== 0) return { ok: false, step: { ...step, text: failureLine(result), ms: result.ms } }
  try {
    const value = parse(result.stdout)
    return { ok: true, value, step: { ...step, ok: true, text: summarize(value), ms: result.ms } }
  } catch {
    return { ok: false, step: { ...step, text: `unexpected output: ${result.stdout.slice(0, 120)}`, ms: result.ms } }
  }
}

