import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { desktopEnv, run } from './process.mjs'

// The worker runs inside Orca's own binary (ELECTRON_RUN_AS_NODE), so Orca's CLI ships beside it.
// Verified on Windows; check the layout before relying on it on macOS.
export function orcaCliPath(execPath = process.execPath, platform = process.platform) {
  const cli = join(dirname(execPath), 'resources', 'bin', platform === 'win32' ? 'orca.exe' : 'orca')
  return existsSync(cli) ? cli : null
}

// `environment` sends the command to a paired Orca server (a VPS, say) instead of this desktop's runtime.
export async function orcaCli(args, { signal, environment } = {}) {
  const cli = orcaCliPath()
  if (!cli) throw new Error(`Orca CLI not found beside ${process.execPath}`)
  const name = `orca ${args.slice(0, 2).join(' ')}${environment ? ` on ${environment}` : ''}`
  const target = environment ? ['--environment', environment] : []
  const { code, stdout } = await run(cli, [...args, ...target, '--json'], { env: desktopEnv(), signal })
  let reply
  try {
    reply = JSON.parse(stdout)
  } catch {
    throw new Error(`${name} printed no JSON (exit ${code})`)
  }
  if (!reply.ok) throw new Error(`${name}: ${reply.error?.message ?? 'failed'}`)
  return reply.result
}

import { orcaCli } from './orca-cli.mjs'

// Host API 1.0's readContext names the focused workspace's branch and terminals but not its path.
// A terminal handle identifies the workspace exactly; branch plus name is the fallback when it has none.
// A workspace on a paired Orca server (a VPS) is not in this desktop's runtime at all: readContext then
// gives its repo's name, an empty branch and no terminals, so the paired servers are asked as well.
export async function resolveFocusedWorkspace(orca, { signal } = {}) {
  const context = await orca.host.call('workspace.readContext', {}, { signal })
  if (!context) return { context: null, path: null, via: 'none', candidates: [] }
  const [terminal] = context.terminals
  if (terminal) {
    const result = await orcaCli(['terminal', 'show', '--terminal', terminal.id], { signal })
    const path = (result.terminal ?? result).worktreePath
    if (path) return { context, path, via: 'terminal', candidates: [path] }
  }
  const { worktrees, hostScope } = await orcaCli(['worktree', 'list', '--limit', '500'], { signal })
  const candidates = matchWorktrees(worktrees, context).map((worktree) => worktree.path)
  if (candidates.length > 0 || context.terminals.length > 0) {
    return { context, path: candidates.length === 1 ? candidates[0] : null, via: 'branch', candidates }
  }
  return resolveOnServers(context, pairedServers(hostScope), { signal })
}

async function resolveOnServers(context, environments, { signal }) {
  const unreachable = []
  const found = await Promise.all(
    environments.map(async (environment) => {
      try {
        const [{ repos }, { worktrees }] = await Promise.all([
          orcaCli(['repo', 'list'], { signal, environment }),
          orcaCli(['worktree', 'list', '--limit', '500'], { signal, environment })
        ])
        return matchServerWorktrees(worktrees, repos, context).map((match) => ({ ...match, environment }))
      } catch (error) {
        unreachable.push(`${environment}: ${error.message}`)
        return []
      }
    })
  )
  const matches = found.flat()
  const candidates = matches.map((match) => `${match.environment} ${match.worktree.path}`)
  if (matches.length !== 1) return { context, path: null, via: 'server', candidates, unreachable }
  const [{ environment, worktree, repo }] = matches
  return {
    context,
    path: worktree.path,
    via: 'server',
    candidates,
    unreachable,
    server: { environment, branch: shortBranch(worktree.branch), repoUrl: repo?.gitRemoteIdentity?.remoteUrl ?? null }
  }
}

// Orca's CLI reports full refs; readContext reports short branch names.
export function shortBranch(ref = '') {
  return ref.replace(/^refs\/heads\//, '')
}

export function matchWorktrees(worktrees, { branch, displayName }) {
  return worktrees.filter(
    (worktree) =>
      !worktree.isArchived && shortBranch(worktree.branch) === branch && worktree.displayName === displayName
  )
}

// The paired Orca servers a local listing left out, by the name `--environment` takes. SSH hosts
// without a server of their own have no selector, and the CLI can't reach them.
export function pairedServers(hostScope) {
  return (hostScope?.omittedHostSelectors ?? [])
    .map((host) => /^--environment (.+)$/.exec(host.selector ?? '')?.[1])
    .filter(Boolean)
}

// A server's workspace reaches readContext with its repo's display name and no branch. Should Orca
// start sending the workspace's own name and branch, those match the way local ones do.
export function matchServerWorktrees(worktrees, repos, context) {
  const repoById = new Map(repos.map((repo) => [repo.id, repo]))
  return worktrees
    .filter((worktree) => !worktree.isArchived)
    .map((worktree) => ({ worktree, repo: repoById.get(worktree.repoId ?? worktree.id.split('::')[0]) }))
    .filter(({ worktree, repo }) =>
      context.branch
        ? shortBranch(worktree.branch) === context.branch && worktree.displayName === context.displayName
        : repo?.displayName === context.displayName
    )
}

import { tmpdir } from 'node:os'

// Orca reports WSL workspaces as UNC paths, while the plugin worker always runs on the desktop host.
// Entire has to run where the repo and its login live, so each workspace path maps to a host.

const WSL_UNC = /^\\\\wsl(?:\.localhost|\$)\\([^\\]+)(\\.*)?$/i

export function workspaceHost(workspacePath) {
  const match = WSL_UNC.exec(workspacePath.replaceAll('/', '\\'))
  if (!match) return { kind: 'local', path: workspacePath }
  return { kind: 'wsl', distro: match[1], path: (match[2] ?? '\\').replaceAll('\\', '/') }
}

// A workspace on a paired Orca server (a VPS). The worker can't run anything there: Orca's SSH key
// needs a passphrase and the CLI has no way to run a command without opening a terminal tab. Trails and
// findings live on Entire's server, though, so this desktop's Entire reads them by repository and
// branch. Status, checkpoints and the diff need the checkout and stay out of reach.
export function serverHost({ environment, path, repoUrl, branch }) {
  return { kind: 'server', environment, path, repo: safeRepoUrl(repoUrl), branch }
}

// The remote URL comes from Orca and goes to Entire as one argument; it must not read as a flag.
export function safeRepoUrl(url) {
  return typeof url === 'string' && /^[\w.+-]+(?::\/\/|@)[^\s]{1,400}$/.test(url) && !url.startsWith('-') ? url : null
}

export function entireCommand(host, args) {
  if (host.kind === 'wsl') {
    // A login shell puts ~/.local/bin on PATH; "$@" passes each argument through without re-parsing.
    return {
      command: 'wsl.exe',
      args: ['-d', host.distro, '--cd', host.path, '-e', 'bash', '-lc', 'exec entire "$@"', 'entire', ...args]
    }
  }
  // Outside any checkout, so only --repo and --branch say which repository Entire reads.
  if (host.kind === 'server') return { command: 'entire', args, cwd: tmpdir() }
  return { command: 'entire', args, cwd: host.path }
}

export function gitCommand(host, args) {
  if (host.kind === 'server') throw new Error(`git runs only on ${host.environment}`)
  if (host.kind === 'wsl') return { command: 'wsl.exe', args: ['-d', host.distro, '--cd', host.path, '-e', 'git', ...args] }
  return { command: 'git', args, cwd: host.path }
}

import { failureLine, runEntire } from './entire-cli.mjs'
import { diffStat, safeRef } from './git.mjs'
import { serverHost, workspaceHost } from './hosts.mjs'
import { trailSummary } from './trail.mjs'
import { resolveFocusedWorkspace } from './workspace.mjs'

const VERSION = { key: 'version', label: 'Entire CLI', args: ['--version'], parse: (out) => out.trim().split('\n')[0] }

// Each step keeps its own outcome, so one failed call (a branch without a trail, say) hides nothing else.
// `byRepo` steps read Entire's server and also work for a paired server's workspace, given --repo and
// --branch; the others read the checkout.
const STEPS = [
  {
    key: 'status',
    label: 'Repo',
    args: ['status', '--json'],
    parse: JSON.parse,
    summarize: (status) =>
      status.enabled ? `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}` : 'Entire is not enabled here'
  },
  // A branch without a trail is normal, so this step reports instead of failing the check.
  {
    key: 'trail',
    label: 'Trail',
    args: ['trail', 'show', '--json'],
    byRepo: true,
    optional: true,
    parse: JSON.parse,
    summarize: (trail) => `#${trail.number} ${trail.title} · ${trail.status}`
  },
  {
    key: 'checkpoints',
    label: 'Checkpoints',
    args: ['checkpoint', 'list', '--json'],
    parse: JSON.parse,
    summarize: (list) => `${list.length} on this branch`
  }
]

// Fetched alongside the steps for the panel only: the connection check doesn't report them. Every status,
// so resolved findings and how they were fixed show too, as in Entire's web view.
const FINDINGS = {
  key: 'findings',
  label: 'Findings',
  args: ['trail', 'finding', 'list', '--status', 'any', '--freshness', 'any', '--json'],
  byRepo: true,
  parse: JSON.parse
}

// The panel keeps the newest checkpoints only.
const CHECKPOINT_LIMIT = 20

// Everything the panel and "Entire: Check connection" show for the focused workspace.
export async function collectSnapshot(orca, { signal } = {}) {
  const snapshot = { at: new Date().toISOString(), workspace: null, problem: null, steps: [], data: {} }

  let resolved
  try {
    resolved = await resolveFocusedWorkspace(orca, { signal })
  } catch (error) {
    return { ...snapshot, problem: `Workspace lookup failed: ${error.message}` }
  }
  const { context, path, via, candidates, server, unreachable = [] } = resolved
  if (!context) return { ...snapshot, problem: 'No workspace is focused' }
  const workspace = {
    name: context.displayName,
    branch: context.branch,
    terminals: context.terminals.map((terminal) => terminal.id),
    path,
    via
  }
  if (!path) return { ...snapshot, workspace, problem: unresolved(context, via, candidates, unreachable) }

  let host = workspaceHost(path)
  if (server) {
    host = serverHost({ ...server, path })
    // readContext gives a server workspace's repo name and no branch; the panel shows the real branch.
    workspace.server = { environment: server.environment, branch: server.branch }
    workspace.where = `${server.environment} ${path}`
    if (!host.repo) return { ...snapshot, workspace, problem: `${path} on ${server.environment} has no origin remote, so Entire can't tell which repository it is.` }
    if (!safeRef(host.branch)) return { ...snapshot, workspace, problem: `${path} on ${server.environment} is on no branch Entire can read.` }
  } else {
    workspace.where = host.kind === 'wsl' ? `WSL ${host.distro} ${host.path}` : path
  }

  const version = await runStep(host, VERSION, signal)
  if (!version.ok) return { ...snapshot, workspace, steps: [version.step] }
  const [findings, ...results] = await Promise.all([FINDINGS, ...STEPS].map((step) => runStep(host, step, signal)))
  const data = Object.fromEntries(results.filter((result) => result.ok).map((result) => [result.step.key, result.value]))
  if (data.checkpoints) data.checkpoints = data.checkpoints.slice(0, CHECKPOINT_LIMIT)
  if (data.trail) {
    const found = findings.ok ? findings.value : null
    const base = safeRef(found?.trail?.base)
    const diff = base && host.kind !== 'server' ? await diffStat(host, base, { signal }) : null
    data.trail = trailSummary(data.trail, { findings: found, diff })
  }
  return { ...snapshot, workspace, steps: [version.step, ...results.map((result) => result.step)], data }
}

function unresolved(context, via, candidates, unreachable) {
  const name = context.branch ? `${context.displayName} on ${context.branch}` : context.displayName
  const offline = unreachable.length > 0 ? ` (couldn't ask ${unreachable.join('; ')})` : ''
  if (via === 'server' && candidates.length > 1) {
    // Orca names only the repo of a paired server's workspace, so its worktrees look alike.
    return `${name}: ${candidates.length} workspaces of this repository match on paired servers, and Orca doesn't tell plugins which one is focused.`
  }
  if (candidates.length > 0) {
    // Without a terminal, only branch and name identify the workspace, and many repos share "main".
    return `${name}: ${candidates.length} workspaces match it. Open a terminal in it and try again.`
  }
  return `${name}: no workspace matches it${offline}. Open a terminal in it and try again.`
}

async function runStep(host, { key, label, args, byRepo = false, optional = false, parse, summarize = (value) => value }, signal) {
  const step = { key, label, optional, ok: false }
  if (host.kind === 'server' && key !== 'version') {
    // On a paired server only Entire's server is in reach; say so instead of failing.
    if (!byRepo) return { ok: false, step: { ...step, optional: true, text: `read only on ${host.environment}` } }
    args = [...args, '--repo', host.repo, '--branch', host.branch]
  }
  let result
  try {
    result = await runEntire(host, args, { signal })
  } catch (error) {
    return { ok: false, step: { ...step, text: error.message } }
  }
  if (result.code !== 0) return { ok: false, step: { ...step, text: explainFailure(host, result), ms: result.ms } }
  try {
    const value = parse(result.stdout)
    return { ok: true, value, step: { ...step, ok: true, text: summarize(value), ms: result.ms } }
  } catch {
    return { ok: false, step: { ...step, text: `unexpected output: ${result.stdout.slice(0, 120)}`, ms: result.ms } }
  }
}

// Entire answers a repository it doesn't track with a bare 404.
function explainFailure(host, result) {
  const line = failureLine(result)
  if (host.kind === 'server' && /repository not found/i.test(line)) return "this repository isn't on Entire"
  return line
}

